// ── Build and walk a simple AST manually ─────────────────────────

// Node constructors (matching ESTree-like shape)
const Literal = (value)       => ({ type: 'Literal', value });
const Identifier = (name)     => ({ type: 'Identifier', name });
const BinaryExpr = (op, l, r) => ({ type: 'BinaryExpression', operator: op, left: l, right: r });
const ReturnStmt = (arg)      => ({ type: 'ReturnStatement', argument: arg });
const FuncDecl = (name, params, body) => ({
  type: 'FunctionDeclaration',
  id: Identifier(name),
  params: params.map(Identifier),
  body: { type: 'BlockStatement', body }
});

// AST for: function add(a, b) { return a + b; }
const ast = FuncDecl('add', ['a', 'b'], [
  ReturnStmt(BinaryExpr('+', Identifier('a'), Identifier('b')))
]);

console.log(JSON.stringify(ast, null, 2).slice(0, 300) + '...');

// ── Tree walker (depth-first visitor) ────────────────────────────
function walk(node, visitor) {
  if (!node || typeof node !== 'object') return;
  const fn = visitor[node.type];
  if (fn) fn(node);
  // recurse into all object/array children
  for (const key of Object.keys(node)) {
    const child = node[key];
    if (Array.isArray(child)) child.forEach(c => walk(c, visitor));
    else if (child && typeof child === 'object' && child.type) walk(child, visitor);
  }
}

// ── Visitor: collect all identifiers ─────────────────────────────
const identifiers = [];
walk(ast, {
  Identifier(node) { identifiers.push(node.name); }
});
console.log('Identifiers found:', identifiers);
// Identifiers found: [ 'add', 'a', 'b', 'a', 'b' ]

// ── Visitor: evaluate the return expression (simple interpreter) ──
function evalNode(node, env) {
  if (node.type === 'Literal')     return node.value;
  if (node.type === 'Identifier')  return env[node.name];
  if (node.type === 'BinaryExpression') {
    const l = evalNode(node.left, env);
    const r = evalNode(node.right, env);
    if (node.operator === '+') return l + r;
    if (node.operator === '-') return l - r;
    if (node.operator === '*') return l * r;
  }
  throw new Error(`Cannot evaluate node: ${node.type}`);
}

const returnExpr = ast.body.body[0].argument; // a + b
console.log(evalNode(returnExpr, { a: 3, b: 7 })); // 10

// ── Using acorn (real JS parser) ─────────────────────────────────
// In Node.js with acorn installed:
// const acorn = require('acorn');
// const ast = acorn.parse('const x = 1 + 2', { ecmaVersion: 2020 });

// Typical ESTree node shapes (no library needed to understand the shape)
const exampleNodes = {
  // Variable declaration: const x = 42
  VariableDeclaration: {
    type: 'VariableDeclaration', kind: 'const',
    declarations: [{
      type: 'VariableDeclarator',
      id:   { type: 'Identifier', name: 'x' },
      init: { type: 'Literal', value: 42, raw: '42' }
    }]
  },
  // Function call: console.log('hi')
  CallExpression: {
    type: 'CallExpression',
    callee: { type: 'MemberExpression',
              object: { type: 'Identifier', name: 'console' },
              property: { type: 'Identifier', name: 'log' } },
    arguments: [{ type: 'Literal', value: 'hi' }]
  }
};
console.log('Node types:', Object.keys(exampleNodes));

// ── Tools built on ASTs ────────────────────────────────────────────
// Tool         | What it does with the AST
// ------------ | -----------------------------------------
// ESLint       | Visitor rules flag bad patterns
// Babel        | Transform nodes, re-emit JS source
// Prettier     | Ignore original text, print AST cleanly
// TypeScript   | Add type nodes, check consistency
// Webpack      | Trace import/export edges for bundling
// Jest         | Transform test files via Babel AST plugin

// ── Writing an ESLint-style rule ─────────────────────────────────
const noConsoleLintRule = {
  // Called by the traversal engine for each CallExpression node
  CallExpression(node) {
    const callee = node.callee;
    if (callee.type === 'MemberExpression' &&
        callee.object.name === 'console') {
      console.warn(`Lint: no-console violation at callee '${callee.property.name}'`);
    }
  }
};
walk(exampleNodes.CallExpression, noConsoleLintRule);
// Lint: no-console violation at callee 'log'
